package com.wultra.security.powerauth.app.server.service.util;

import com.wultra.security.powerauth.app.server.service.model.SdkConfiguration;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

/**
 * Test for SDK data writer.
 *
 * @author Roman Strobl, roman.strobl@wultra.com
 */
public class SdkConfigurationSerializerTest {

    @Test
    public void testSerializeAndDeserialize() {
        final String appKey = "w4+hAeogFLTZjcSjPwbG2g==";
        final String appSecret = "Szls/7JWbKN+FAOijHcsPA==";
        final String masterPublicKeyP256 = "BEEOwljSgItBIAnzr3f7K36s+KKoUzC8LE+K+7Dy0X6iAkcPXAjLP1KKPxdqyM/iihHAcW5x/WzJPCbtytcJo2w=";
        final String masterPublicKeyP384 = "BCkhOMEqwc7SZu1TmIt8iKf8tnU+ERNynIa8tZliWwyWgirOngqprNEDKig0Ch3D0HWqeIaKsLNiDS3mrJCiZFBdnRQf3t4qGazxNcW7cPq6ye0OGHPGHh0/Ph9FH6Lrmw==";
        final String masterPublicKeyMlDsa65 = "";
        final String expectedValue = "";
        final String serialized = SdkConfigurationSerializer.serialize(new SdkConfiguration(appKey, appSecret, masterPublicKeyP256, masterPublicKeyP384, masterPublicKeyMlDsa65));
        assertEquals(expectedValue, serialized);
        final SdkConfiguration config = SdkConfigurationSerializer.deserialize(serialized);
        assertNotNull(config);
        assertEquals(appKey, config.appKey());
        assertEquals(appSecret, config.appSecret());
        assertEquals(masterPublicKeyP256, config.masterPublicKeyP256());
        assertEquals(masterPublicKeyP384, config.masterPublicKeyP384());
        assertEquals(masterPublicKeyMlDsa65, config.masterPublicKeyMlDsa65());
    }

}